import Axios from '@/server'
import type { Result } from '@/server/types'
import { PlatformUserTypes } from './types'

// ==================== 【配送员管理】 ====================

/**
 * 【配送员管理】获取配送员详情
 * @param userId 用户ID
 */
export const getCourierUserDetail = (userId: number) =>
  Axios.request<Result<PlatformUserTypes.DetailCourierUserRes>>({
    url: `/admin/platform-user/courier-user/${userId}/detail`,
    method: 'GET'
  })

/**
 * 【配送员管理】编辑配送员
 * @param userId 用户ID
 * @param data 配送员信息
 */
export const editCourierUser = (userId: number, data: PlatformUserTypes.EditCourierUserReq) =>
  Axios.request<Result>({
    url: `/admin/platform-user/courier-user/${userId}/edit`,
    method: 'POST',
    data
  })

/**
 * 【配送员管理】修改配送员状态
 * @param userId 用户ID
 * @param data 状态信息
 */
export const updateCourierUserStatus = (
  userId: number,
  data: PlatformUserTypes.UpdateStatusCourierUserReq
) =>
  Axios.request<Result>({
    url: `/admin/platform-user/courier-user/${userId}/update-status`,
    method: 'POST',
    data
  })

/**
 * 【配送员管理】添加配送员
 * @param data 配送员信息
 */
export const addCourierUser = (data: PlatformUserTypes.AddCourierUserReq) =>
  Axios.request<Result>({
    url: '/admin/platform-user/courier-user/add',
    method: 'POST',
    data
  })

/**
 * 【配送员管理】配送员列表
 * @param params 查询参数
 */
export const getCourierUserList = (params?: PlatformUserTypes.CourierUserListReq) =>
  Axios.request<Result<PlatformUserTypes.CourierUserListRes>>({
    url: '/admin/platform-user/courier-user/list',
    method: 'GET',
    params
  })

